function zohoDomains() {
  return Object.keys(ZOHO_TOOLKIT).sort();
}

function zohoToolsInDomain(domain) {
  if (!ZOHO_TOOLKIT[domain]) return [];
  return Object.keys(ZOHO_TOOLKIT[domain]).sort();
}

function zohoToolInfo(domain, tool) {
  if (!ZOHO_TOOLKIT[domain]) return null;
  if (ZOHO_TOOLKIT[domain][tool]) return ZOHO_TOOLKIT[domain][tool];
  // Master pricing list tool names are like "Zoho AlarmsOne"; toolkit keys
  // are bare ("AlarmsOne"). Strip the prefix and try again.
  const bare = (tool || '').replace(/^zoho\s+/i, '');
  return ZOHO_TOOLKIT[domain][bare] || null;
}

// Loose match against the priced master tool list (assets/data.js / Admin),
// purely to pre-tick a matching row in Team & Tools -- never edits pricing.
function findMasterToolMatch(zohoToolName) {
  const needle = (zohoToolName || '').toLowerCase().replace(/[_\s]+/g, ' ').trim();
  if (!needle) return null;
  return STATE.tools.find(t => {
    const hay = (t.tool || '').toLowerCase();
    return hay === needle || hay.includes(needle) || needle.includes(hay);
  }) || null;
}

// Same loose match, but against the Admin master list (all priced editions),
// for the Knowledge Base reference view.
function matchMasterToolEditions(zohoToolName) {
  const needle = (zohoToolName || '').toLowerCase().replace(/[_\s]+/g, ' ').trim();
  if (!needle) return [];
  return MASTER_TOOLS.filter(t => {
    const hay = (t.tool || '').toLowerCase();
    return hay === 'zoho ' + needle || hay.includes(needle);
  });
}
